import images from "@/generated/basemap-images.json";

/**
 * Pre-rendered Mapbox basemap snapshots, keyed by style URL, for places where live
 * Mapbox tiles can't load (the claude.ai Artifact sandbox). Generated by
 * `npm run fetch:basemaps` (or a Mapbox MCP session) into src/generated/basemap-images.json.
 */
export interface BasemapImage {
  /** [west, south, east, north] the image covers. */
  bbox: [number, number, number, number];
  /** data: URI of the rendered style. */
  src: string;
}

export const BASEMAP_IMAGES = images as Record<string, BasemapImage>;
